#include <stdio.h>
int R_Sum(int M1[100][100],int row,int clm)//Fuction for calculating sum of Row
{
    int i,j,rsum;
    for(i=0;i<row;i++)
    {
        rsum=0;
        for(j=0;j<clm;j++)
        {
            rsum=rsum+M1[i][j];
        }
    }
    return rsum;
}
